using System;using System.IO;using UnityEngine;using UnityEditor;
public static class CaptureShopCorrections {
 static void Capture(Camera camera,Vector3 position,Vector3 target,float fov,string file,int width,int height){var originalPos=camera.transform.position;var originalRot=camera.transform.rotation;float originalFov=camera.fieldOfView;var originalTarget=camera.targetTexture;var oldActive=RenderTexture.active;var rt=RenderTexture.GetTemporary(width,height,24);Texture2D tex=null;try{camera.transform.SetPositionAndRotation(position,Quaternion.LookRotation(target-position));camera.fieldOfView=fov;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(file,tex.EncodeToPNG());}finally{camera.transform.SetPositionAndRotation(originalPos,originalRot);camera.fieldOfView=originalFov;camera.targetTexture=originalTarget;RenderTexture.active=oldActive;RenderTexture.ReleaseTemporary(rt);if(tex)UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){var camera=SceneView.lastActiveSceneView.camera;Capture(camera,new Vector3(14,3.15f,43),new Vector3(14,3.15f,57),50,"output/NewMap/ShopCorrections/Shop.png",1200,900);Capture(camera,new Vector3(14,2.35f,51),new Vector3(13.6f,1.18f,54.9f),55,"output/NewMap/ShopCorrections/FlatTools.png",1100,800);Capture(camera,new Vector3(0,1.8f,35),new Vector3(5,2.8f,76),60,"output/NewMap/ShopCorrections/RoadTransition.png",1200,850);return "Three review captures saved; Scene View camera restored";}
}
